const ALL = [
  ...MIR4_QUESTS_MAIN,
  ...MIR4_QUESTS_SIDE,
  ...MIR4_QUESTS_REPEATABLE,
  ...MIR4_QUESTS_CITYPROFESSION,
];
export const MIR4_QUESTS_ARC: readonly Mir4ArcQuest[] = ALL;

const BY_ID = new Map(ALL.map((quest) => [quest.questId, quest]));
export function mir4ArcQuest(questId: string): Mir4ArcQuest | null {
  return BY_ID.get(questId) ?? null;
}
